function StackCard({ study, index, total }: { study: (typeof studies)[number]; index: number; total: number }) {
  const ref = useRef<HTMLDivElement>(null)
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start end", "start start"],
  })
  const scale = useTransform(scrollYProgress, [0, 1], [0.94, 1])

  return (
    <div
      ref={ref}
      className="sticky"
      style={{ top: `${96 + index * 26}px` }}
    >
      <motion.div
        style={{ scale }}
        className={`relative overflow-hidden rounded-[2rem] border border-black/5 bg-gradient-to-br ${study.gradient} p-8 shadow-[0_30px_80px_-40px_rgba(11,11,20,0.35)] backdrop-blur-xl md:p-12`}
      >
        <div className="absolute inset-0 bg-white/70" />
        <div className="relative grid gap-8 md:grid-cols-[1.4fr_1fr] md:items-center">
          <div>
            <div className="flex items-center gap-3">
              <span className="text-sm font-bold tabular-nums text-brand-purple">{study.n}</span>
              <span className="text-xs font-semibold uppercase tracking-[0.2em] text-muted-foreground">
                {study.sector}
              </span>
            </div>
            <h3 className="mt-4 text-2xl font-bold tracking-tight text-ink md:text-3xl">
              {study.name}
            </h3>
            <p className="mt-4 max-w-lg text-lg leading-relaxed text-ink/70">
              {study.headline}
            </p>
            <div className="mt-6 inline-flex items-center gap-1.5 text-sm font-medium text-muted-foreground">
              {study.place}
              <ArrowUpRight className="h-4 w-4" />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4 md:grid-cols-1">
            {study.stats.map((s) => (
              <div key={s.v} className="rounded-2xl border border-black/5 bg-white/80 p-5">
                <div className="text-3xl font-bold text-ink md:text-4xl">{s.k}</div>
                <div className="mt-1 text-xs leading-snug text-muted-foreground">{s.v}</div>
              </div>
            ))}
          </div>
        </div>
      </motion.div>
    </div>
  )
}

