import { cn } from "@/lib/utils"

/**
 * Webfluence "WF." wordmark — a rounded gradient tile with the WF monogram,
 * followed by the studio name. Inspired by the brand flyer.
 */
export function Logo({
  className,
  showWordmark = true,
  invert = false,
}: {
  className?: string
  showWordmark?: boolean
  invert?: boolean
}) {
  return (
    <span className={cn("inline-flex items-center gap-2.5", className)}>
      <span className="relative grid h-9 w-9 place-items-center rounded-xl bg-brand-gradient shadow-[0_8px_20px_-8px_rgba(124,58,237,0.6)]">
        <span className="text-[15px] font-extrabold leading-none tracking-tight text-white">
          WF
        </span>
      </span>
      {showWordmark && (
        <span
          className={cn(
            "text-xl font-bold tracking-tight",
            invert ? "text-white" : "text-ink",
          )}
        >
          Webfluence<span className="text-brand-cyan">.</span>
        </span>
      )}
    </span>
  )
}
