"use client"

import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { Plus } from "lucide-react"
import { cn } from "@/lib/utils"

const faqs = [
  {
    q: "How does the one-week discovery sprint work?",
    a: "We embed with your team for five working days. By Friday you have a written spec, a fixed-fee quote, and a Loom walkthrough of a working scaffold — before you commit to anything. Discovery is billed separately and credited in full against the project fee if you proceed.",
  },
  {
    q: "What does “fixed-fee” actually mean?",
    a: "After discovery we lock a scope and a price. If the scope doesn't change, the price doesn't change. If we under-estimated the effort, that's on us. If you add scope, we re-quote transparently before writing a line of code.",
  },
  {
    q: "Do you work with international clients?",
    a: "About 40% of our revenue is international — UK, UAE, US, and EU. We overlap with GMT+5 and flex hours for US-East calls. All communication is in English, all contracts are in USD or PKR, and we've shipped production code under GDPR, SOC 2, and PCI-DSS constraints.",
  },
  {
    q: "Who owns the code and infrastructure?",
    a: "You do. Repo, CI/CD pipelines, cloud accounts, vendor API keys, architectural decision records — everything is in your name from day one. We don't gate-keep access and we don't charge exit fees.",
  },
  {
    q: "What happens after launch?",
    a: "Every feature ships with a 30-day warranty. After that, we offer an optional care retainer — never assumed, never bundled in by default.",
  },
]

export function Faq() {
  const [open, setOpen] = useState<number | null>(0)

  return (
    <section id="faq" className="relative bg-secondary/40 py-28 md:py-36">
      <div className="container mx-auto px-6">
        <div className="grid gap-12 lg:grid-cols-[0.8fr_1.2fr]">
          <div>
            <span className="text-sm font-semibold uppercase tracking-[0.2em] text-brand-purple">
              06 — FAQ
            </span>
            <h2 className="mt-5 text-3xl font-bold tracking-tight text-ink md:text-5xl">
              Questions we hear in every discovery call.
            </h2>
          </div>

          <div className="divide-y divide-black/5 rounded-3xl border border-black/5 bg-white">
            {faqs.map((f, i) => (
              <div key={f.q}>
                <button
                  onClick={() => setOpen(open === i ? null : i)}
                  className="flex w-full items-center justify-between gap-4 px-6 py-5 text-left"
                >
                  <span className="font-semibold text-ink">{f.q}</span>
                  <Plus
                    className={cn(
                      "h-5 w-5 flex-none text-brand-purple transition-transform duration-300",
                      open === i && "rotate-45",
                    )}
                  />
                </button>
                <AnimatePresence initial={false}>
                  {open === i && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.3 }}
                      className="overflow-hidden"
                    >
                      <p className="px-6 pb-6 text-sm leading-relaxed text-muted-foreground">
                        {f.a}
                      </p>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}
